"""Restore the original milestone collection; evidence relevance is a separate editorial layer."""
from pathlib import Path
import json,hashlib,shutil
ROOT=Path(__file__).resolve().parents[1]
raw=json.loads((ROOT/'research/imported.json').read_text())
evidence=json.loads((ROOT/'web/data/evidence.json').read_text())
value=lambda row,col:row['cells'].get(col,{}).get('value','')
dedup={(value(r,'F'),value(r,'A')):r for r in raw['rawWorkbook']['Deduplication'][1:]}
entries=[]
for e in raw['entries']:
 p=e['provenance'];row=dedup.get((e['id'],e['duplicate']))
 entries.append({k:e[k] for k in ['id','field','title','description','impact','category']}|{'status':'proposed-milestone','provenance':p,'originalSourceLinks':e['sourceLinks'],'duplicateOf':e['duplicate'] if e['duplicate']!='FALSE' else None,'duplicateProvenance':{'workbook':'AI_Takeoff_Master_Table.xlsx','sheet':'Deduplication','row':row['row'],'rationale':value(row,'K')} if row else None,'dependencyReview':'not-reviewed','achievementReview':'not-assessed'})
A=[]
def attach(id,result,milestone,label,relevance,boundary):A.append(dict(id=id,resultId=result,milestoneId=milestone,kind=label,relevance=relevance,boundary=boundary,review='editorial-relevance-review',provenance={'basis':'Interpretation of the separately linked scoped research result; not an author claim about the original milestone.','checkedAt':'2026-10-30'}))
attach('EA-01','EV-CLIP','MLC-03','partial-evidence','Zero-shot transfer is relevant to the milestone’s interest in learning with few or no task-specific examples.','CLIP uses large-scale pretraining. These benchmarks do not establish infant-like sample efficiency or mastery of arbitrary concepts.')
attach('EA-02','EV-GNS','MLC-06','related-evidence','Learned physical simulation is related to the simulation aspect of this proposed reasoning capability.','Simulation of tested systems is not discovery of causal structure or reliable counterfactual reasoning. This is context, not a demonstration of the milestone.')
attach('EA-03','EV-AF','BCH-03','related-evidence','Sequence-based structure prediction is relevant background to the ambition of predicting protein folding.','A predicted structure is not an in-vivo folding pathway, chaperone requirement or misfolding-risk model. The cited paper does not establish this folding code.')
attach('EA-04','EV-RT2','ROB-07','partial-evidence','Some reported robot command interpretation and object-selection behaviors are relevant to reasoning in embodied tasks.','The evaluated behaviors do not establish general physical common sense, causal reasoning or reliability in arbitrary new environments.')
attach('EA-05','EV-DIFF','ROB-01','partial-evidence','Evaluated visuomotor manipulation is a narrower capability relevant to the original universal manipulation ambition.','Selected benchmark tasks do not demonstrate manipulation of any object, universal dexterity or human-level adaptability.')
attach('EA-06','EV-GNOME','CRX-02','partial-evidence','Computational candidate-crystal prediction is relevant to the original crystal-structure prediction goal.','The study does not demonstrate all polymorphs, co-crystals and hydrates for arbitrary compositions under arbitrary conditions with the proposed accuracy and speed.')
attach('EA-07','EV-GNOME','MAS-03','related-evidence','The paper’s screening of solid-electrolyte candidates is relevant to materials exploration for this battery ambition.','Candidate screening does not establish the original energy density, charging time, cycle life, dendrite behavior or absolute-safety assertion.')
attach('EA-08','EV-OSK','LON-05','partial-evidence','Retinal-cell reprogramming effects in mice are a scoped experimental result related to the epigenetic reprogramming ambition.','Mouse retinal results do not establish complete, safe reprogramming throughout the body or systemic human rejuvenation.')
attach('EA-09','EV-PACE','LON-09','partial-evidence','A longitudinally informed methylation measure is relevant to the ambition of measuring biological aging.','It is not a demonstrated predictor of remaining healthy lifespan or a validated measure of aging reversal for arbitrary interventions.')
attach('EA-10','EV-CALERIE','LON-09','qualification','A small change in one methylation measure, alongside no significant changes in others, qualifies how such aging measures can be interpreted.','The authors call for clinical endpoint follow-up. This result does not prove that biomarker changes measure rejuvenation or longer healthy life.')
relationships=[
 dict(id='HYP-01',fromId='LON-09',toId='LON-01',kind='accelerator',epistemicStatus='hypothesis',rationale='A validated aging measure could help evaluate proposed systemic interventions and prioritize experiments. It is not logically required: trials can measure clinical outcomes directly.',uncertainty='A useful surrogate has not been established by the attached studies. A biomarker response could fail to track clinical benefit; this link is not demonstrated causal necessity.',resultIds=['EV-PACE','EV-CALERIE'],provenance={'origin':'New editorial relationship proposal','checkedAt':'2026-10-30','sourceLocator':'DunedinPACE Discussion on surrogate validation; CALERIE abstract on clinical endpoint follow-up.'}),
 dict(id='HYP-02',fromId='CRX-02',toId='MAS-03',kind='accelerator',epistemicStatus='hypothesis',rationale='Improved crystal-structure prediction could help choose electrolyte candidates for testing. The research reports candidate screening, which motivates this proposed research route.',uncertainty='The broad crystal-prediction milestone is not necessary for battery progress. Computed stability does not establish synthesis, interfaces, performance or safety; this is not a proven dependency.',resultIds=['EV-GNOME'],provenance={'origin':'New editorial relationship proposal','checkedAt':'2026-10-30','sourceLocator':'GNoME abstract on solid-electrolyte candidates and conclusion on synthesizability.'})
]
fields=[]
for field in sorted({e['field'] for e in entries}):
 items=[e for e in entries if e['field']==field]
 fields.append(dict(name=field,category=items[0]['category'],count=len(items),sourcePath=items[0]['provenance']['markdown']))
source_dir=ROOT/'web/sources';source_dir.mkdir(exist_ok=True)
for doc in raw['markdown']:
 p=ROOT/doc['path'];assert hashlib.sha256(p.read_bytes()).hexdigest()==doc['sha256'];shutil.copyfile(p,source_dir/p.name)
p=ROOT/'AI_Takeoff_Master_Table.xlsx';assert hashlib.sha256(p.read_bytes()).hexdigest()==raw['workbookSha256'];shutil.copyfile(p,source_dir/p.name)
original={e['id']:e for e in raw['entries']}
for e in entries:
 for key in ['id','field','title','description','impact','category','provenance']:assert e[key]==original[e['id']][key]
assert len(entries)==660 and len(fields)==66 and len(A)==10
out=dict(schemaVersion=3,version='original-collection-2026-10-30-v1',milestones=entries,fields=fields,evidenceAssociations=A,relationships=relationships,sourceWorkbook={'path':'AI_Takeoff_Master_Table.xlsx','sha256':raw['workbookSha256']},history=[{'id':'restore-original-collection','date':'2026-10-30','title':'Original milestones restored as the foundation','description':'Restored all 660 original entries across 66 fields, retaining original wording, IDs, descriptions, impacts, source provenance and 13 duplicate flags. The nine scoped studies are a separate evidence layer, with ten relevance interpretations. Two optional relationship proposals are explicitly hypotheses; no legacy dependency was accepted.'},{'id':'source-correction','date':'2026-10-30','title':'Unsupported prototype assertions removed','description':'Removed invented future windows and success criteria from factual presentation. Original source aspirations remain proposals. Earlier source submissions and prototype records are preserved.'}],policy={'milestones':'Original source proposals and impact assertions; achievement not assessed.','evidence':'Scoped reported findings; relevance is separately identified editorial interpretation.','relationships':'Zero established dependency links. Two optional accelerator hypotheses, sourced and explicitly uncertain. Legacy dependency rows are excluded.','forecasts':'Original workbook forecasts are available only in the source workbook, not asserted as predictions here.'})
(ROOT/'web/data/milestones.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'milestones':len(entries),'fields':len(fields),'duplicateFlags':sum(bool(e['duplicateOf']) for e in entries),'researchResults':len(evidence['results']),'evidenceAssociations':len(A),'milestonesWithEvidence':len({a['milestoneId'] for a in A}),'hypotheses':len(relationships),'establishedDependencies':0,'legacyDependenciesDisplayed':0},indent=2))
